let uplink = msg.payload.uplink_message || {};
let decoded = uplink.decoded_payload || {};

let meta = {};
if(uplink.rx_metadata && uplink.rx_metadata[0]){
  meta = uplink.rx_metadata[0];
}

if(meta.rssi !== undefined) decoded.rssi = meta.rssi;
if(meta.snr !== undefined) decoded.snr = meta.snr;
if(meta.gateway_ids && meta.gateway_ids.gateway_id){
  decoded.gateway_id = meta.gateway_ids.gateway_id;
}

msg.rx_metadata = uplink.rx_metadata || [];

msg.device_id = msg.payload.end_device_ids ? msg.payload.end_device_ids.device_id : "heltec";
msg.payload = decoded;
msg.timestamp = new Date().toISOString();

return msg;

const dev = msg.device_id;
const payload = msg.payload;
let msgs=[];

for(const key in payload){
  let value = payload[key];
  msgs.push({
    topic:`home/${dev}/${key}`,
    payload:value,
    retain:true
  });
}

return [msgs];

const dev = msg.device_id;
const payload = msg.payload;
let msgs = [];

for (const key in payload) {
  let value = payload[key];

  let config = {
    name: key,
    unique_id: `${dev}_${key}`,
    state_topic: `home/${dev}/${key}`,
    force_update: true,
    device: {
      identifiers: [dev],
      name: `Heltec ${dev}`,
      manufacturer: "Heltec",
      model: "CubeCell"
    }
  };

  // Voeg alleen state_class toe als de waarde daadwerkelijk een getal is
  if (typeof value === 'number') {
    config.state_class = "measurement";
  }

  if (key.includes("temp")) {
    config.device_class = "temperature";
    config.unit_of_measurement = "°C";
  }
  else if (key.includes("humid")) {
    config.device_class = "humidity";
    config.unit_of_measurement = "%";
  }
  else if (key.includes("press")) {
    config.device_class = "pressure";
    config.unit_of_measurement = "hPa";
  }
  else if (key.includes("volt") || key.includes("battery")) {
    config.device_class = "voltage";
    config.unit_of_measurement = "V";
  }
  else if (key === "battery_level") {
    config.device_class = "battery";
    config.unit_of_measurement = "%";
  }
  else if (key === "distance") {
    config.unit_of_measurement = "cm";
  }
  else if (key === "rssi") {
    config.unit_of_measurement = "dBm";
  }
  else if (key === "snr") {
    config.unit_of_measurement = "dB";
  }

  msgs.push({
    topic: `homeassistant/sensor/${dev}/${key}/config`,
    payload: JSON.stringify(config),
    retain: true
  });
}

return [msgs];

const dev = msg.device_id;
let last = flow.get(`last_${dev}`)||0;
let now = Date.now();
let interval = last?Math.round((now-last)/1000):0;
flow.set(`last_${dev}`,now);

return [{
  topic:`home/${dev}/uplink_interval`,
  payload:interval,
  retain:false
}];

let table = flow.get('gateway_table') || {};
let rxList = msg.rx_metadata || [];
let now = new Date().toLocaleString('nl-NL', {
  timeZone: 'Europe/Amsterdam',
  year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit',
  hour12: false
}).replace(',', '');

for(let rx of rxList){
  let gw_id = rx.gateway_ids ? rx.gateway_ids.gateway_id : null;
  if(!gw_id) continue;

  if(!table[gw_id]){
    table[gw_id] = {
      gateway_id: gw_id,
      count: 0,
      rssi: null,
      snr: null,
      last_seen: null
    };
  }

  table[gw_id].count++;
  table[gw_id].rssi = rx.rssi !== undefined ? rx.rssi : table[gw_id].rssi;
  table[gw_id].snr = rx.snr !== undefined ? Math.round(rx.snr * 10) / 10 : table[gw_id].snr;
  table[gw_id].last_seen = now;
}

flow.set('gateway_table', table);

let sorted = Object.values(table).sort((a,b) => b.count - a.count);
let count = sorted.length;

let discoveryMsg = {
  topic: 'homeassistant/sensor/heltec/gateways/config',
  payload: JSON.stringify({
    name: 'gateways',
    unique_id: 'heltec_gateways',
    state_topic: 'home/heltec/gateways',
    value_template: '{{ value_json.count }}',
    json_attributes_topic: 'home/heltec/gateways',
    unit_of_measurement: 'gateways',
    icon: 'mdi:radio-tower',
    device: {
      identifiers: ['heltec'],
      name: 'Heltec heltec',
      manufacturer: 'Heltec',
      model: 'CubeCell'
    }
  }),
  retain: true
};

let stateMsg = {
  topic: 'home/heltec/gateways',
  payload: JSON.stringify({
    count: count,
    gateways: sorted
  }),
  retain: true
};

return [[discoveryMsg, stateMsg]];
